let hoodOpen=false,orbit=1.05,orbitY=.36,zoom=1;function refresh(){const c=current();$('balance').textContent=fmt(state.money);$('carName').textContent=c.name;$('carClass').textContent=c.type==='truck'?'TRUCK':c.type==='rally'?'RALLY':c.type==='drag'?'DRAG':'STREET';$('drive').textContent=c.drive;$('ownedCount').textContent=String(state.owned.length).padStart(2,'0')+' АВТО';$('stats').innerHTML=[['Мощность',power()+' л.с.',power()/2000],['Макс. скорость',topSpeed()+' км/ч',topSpeed()/550],['Разгон 0–100',Math.max(1.7,13.2*Math.sqrt(115/power())).toFixed(1)+' сек',Math.min(1,power()/800)]].map(([a,b,v])=>`<div class="stat"><div>${a}<b>${b}</b></div><section class="bar"><i style="width:${Math.min(100,Math.max(12,v*100))}%"></i></section></div>`).join('');$('owned').innerHTML=state.owned.map(id=>{const c=cars.find(x=>x.id===id);return `<button data-car="${id}" class="${id===state.selected?'selected':''}">${c.name}<small>${id===state.selected?'В БОКСЕ':'ВЫБРАТЬ'} &nbsp; / &nbsp; ${c.hp} HP</small></button>`}).join('');$('owned').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.selected=b.dataset.car;replaceCar();refresh();save()});$('colors').innerHTML=['#aaba96','#dddccf','#424b4d','#c35a40','#557e9e','#b6a062'].map(c=>`<button aria-label="Цвет ${c}" style="background:${c}" data-color="${c}" class="${mod().color===c?'selected':''}"></button>`).join('');$('colors').querySelectorAll('button').forEach(b=>b.onclick=()=>{mod().color=b.dataset.color;replaceCar();refresh();save()});}
const modal=$('modal');function show(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;modal.showModal();}function activeTab(t){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===t))}$('close').onclick=()=>modal.close();modal.addEventListener('close',()=>activeTab('garage'));modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
