const upgrades=[['engine','Двигатель','Сток → Sport → V8 → Race',2500],['turbo','Турбонаддув','Больше мощности и выше скорость',1800],['tires','Шины и подвеска','Больше сцепления на асфальте и грунте',1200],['spoiler','Аэропакет','Заднее антикрыло на твоём кузове',900]];
