let mode='garage',speed=0,heading=0,health=100,elapsed=0,cp=0,distance=0,paidDistance=0,crashes=0,hitCooldown=0,finished=false,dragGear=1,countdown=3,rivalCp=0;const keys={};function reward(n){state.money=Math.min(LIMIT,state.money+Math.max(0,Math.round(n)));save();refresh()}
function start(m){camera.clearViewOffset();releaseControls();document.body.classList.add('driving');$('shiftControls').hidden=m!=='drag';mode=m;modal.close();buildWorld(m);garage.visible=false;world.visible=true;scene.background.set(m==='rally'?'#899780':'#82948b');scene.fog.color.copy(scene.background);scene.fog.near=90;scene.fog.far=270;carGroup.position.set(m==='drag'?-3:['race','rally'].includes(m)?-80:0,0,m==='crash'?15:['race','rally'].includes(m)?-80:0);carGroup.rotation.set(0,0,0);bodyParts.forEach(p=>p.scale.set(1,1,1));heading=['race','rally'].includes(m)?-Math.PI/2:0;carGroup.rotation.y=heading;speed=0;health=100;elapsed=0;cp=0;distance=0;paidDistance=0;crashes=0;hitCooldown=0;finished=false;dragGear=1;countdown=['race','rally','drag'].includes(m)?3:0;rivalCp=0;$('garageUI').hidden=true;$('playUI').hidden=false;$('modeName').textContent=modes.find(x=>x[0]===m)[2];$('status').textContent='НА ТРАССЕ';$('hint').textContent='WASD — ЕЗДА · ПРОБЕЛ — РУЧНИК · SHIFT — ПЕРЕДАЧА';$('raceMessage').textContent='';hoodOpen=false;initAudio();}
