function shift(delta=1){if(mode==='drag'&&!finished&&countdown<=0){dragGear=Math.max(1,Math.min(6,dragGear+delta));$('shiftGear').textContent=dragGear;}}$('shiftUp').onclick=()=>shift(1);$('shiftDown').onclick=()=>shift(-1);$('gear').style.cursor='pointer';$('gear').onclick=()=>shift(1);window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(!e.repeat&&k==='shift')shift(1);if(!e.repeat&&k==='control')shift(-1);if(!e.repeat&&k==='r'&&mode!=='garage'){carGroup.position.set(mode==='drag'?-3:cp?checkpoints[cp-1]?.x||0:0,0,cp?checkpoints[cp-1]?.z||0:0);speed=0;heading=0;}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));const touchPointers=new Map();function releaseControls(){touchPointers.clear();Object.keys(keys).forEach(k=>keys[k]=false);document.querySelectorAll('[data-key]').forEach(b=>b.classList.remove('held'));}
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touchPointers.set(e.pointerId,b.dataset.key);keys[b.dataset.key]=true;b.classList.add('held')});const release=e=>{const k=touchPointers.get(e.pointerId);touchPointers.delete(e.pointerId);if(k&&!Array.from(touchPointers.values()).includes(k))keys[k]=false;b.classList.remove('held')};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);b.addEventListener('contextmenu',e=>e.preventDefault());});window.addEventListener('blur',releaseControls);document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseControls()});document.addEventListener('contextmenu',e=>e.preventDefault());
