let audioCtx,osc,gain,sound=false;function initAudio(){if(!sound)return;try{if(!audioCtx){audioCtx=new AudioContext();osc=audioCtx.createOscillator();gain=audioCtx.createGain();osc.type='sawtooth';const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=500;osc.connect(filter);filter.connect(gain);gain.connect(audioCtx.destination);osc.start();}audioCtx.resume();}catch{sound=false}}$('sound').onclick=()=>{sound=!sound;initAudio();$('sound').style.color=sound?'#ff6935':'';toast(sound?'Звук двигателя включён':'Звук выключен')};
const cameraTarget=new T.Vector3(),cameraGoal=new T.Vector3(),carBounds=new T.Box3(),carSize=new T.Vector3(),viewRay=new T.Raycaster();let hiddenGarageMeshes=[];
function frameGarage(snap=false){
carBounds.setFromObject(carGroup);carBounds.getCenter(cameraTarget);carBounds.getSize(carSize);
const title=!$('startScreen').hidden,portrait=innerWidth<650;
const targetX=title&&!portrait?.72:portrait?.35:.43,targetY=portrait?.38:.52;
camera.setViewOffset(innerWidth,innerHeight,(.5-targetX)*innerWidth,(.5-targetY)*innerHeight,innerWidth,innerHeight);
const vfov=T.MathUtils.degToRad(camera.fov),hfov=2*Math.atan(Math.tan(vfov/2)*camera.aspect);
const halfWidth=(Math.abs(Math.cos(orbit))*carSize.x+Math.abs(Math.sin(orbit))*carSize.z)/2;
const halfDepth=(Math.abs(Math.sin(orbit))*carSize.x+Math.abs(Math.cos(orbit))*carSize.z)/2;
const roomX=portrait?.6:title?.43:.56,roomY=portrait?.40:.57;
const distance=Math.max(halfWidth/(Math.tan(hfov/2)*roomX),carSize.y/2/(Math.tan(vfov/2)*roomY))+halfDepth;
const radius=Math.max(6.8,distance)*zoom;
cameraGoal.set(Math.sin(orbit)*Math.cos(orbitY)*radius,Math.sin(orbitY)*radius,-Math.cos(orbit)*Math.cos(orbitY)*radius).add(cameraTarget);
if(snap)camera.position.copy(cameraGoal);else camera.position.lerp(cameraGoal,.12);
camera.lookAt(cameraTarget);camera.updateMatrixWorld(true);
hiddenGarageMeshes.forEach(o=>o.visible=true);hiddenGarageMeshes=[];
garage.updateMatrixWorld(true);
const points=[cameraTarget.clone(),...[-.35,.35].map(x=>cameraTarget.clone().add(new T.Vector3(carSize.x*x,0,0)))];
for(const point of points){const direction=point.clone().sub(camera.position);viewRay.set(camera.position,direction.clone().normalize());viewRay.far=Math.max(0,direction.length()-Math.max(carSize.x,carSize.z)*.3);for(const hit of viewRay.intersectObjects(garage.children,true)){if(hit.object.isMesh&&!hiddenGarageMeshes.includes(hit.object)){hiddenGarageMeshes.push(hit.object);hit.object.visible=false;}}}
}
let dragging=false,lastX,lastY;
$('scene').onpointerdown=e=>{if(mode!=='garage')return;dragging=true;lastX=e.clientX;lastY=e.clientY;$('scene').setPointerCapture(e.pointerId)};
$('scene').onpointermove=e=>{if(!dragging)return;orbit-=(e.clientX-lastX)*.006;orbitY=Math.max(.18,Math.min(.85,orbitY+(e.clientY-lastY)*.004));lastX=e.clientX;lastY=e.clientY;};
$('scene').onpointerup=$('scene').onpointercancel=$('scene').onlostpointercapture=()=>dragging=false;
$('scene').addEventListener('wheel',e=>{if(mode==='garage'){e.preventDefault();zoom=Math.max(.9,Math.min(1.4,zoom+e.deltaY*.0006));}},{passive:false});
