addEventListener('resize',resize);resize();replaceCar();refresh();frameGarage(true);
let last=performance.now();const desired=new T.Vector3(),look=new T.Vector3();function tick(now){requestAnimationFrame(tick);const dt=Math.min((now-last)/1000,.04);last=now;hood.rotation.x=T.MathUtils.lerp(hood.rotation.x,hoodOpen?-1.15:0,.09);if(mode==='garage'){frameGarage();key.position.set(5,14,7);key.target.position.set(0,0,0);}else{const accelerating=keys.w||keys.arrowup,braking=keys.s||keys.arrowdown,steer=(keys.a||keys.arrowleft?1:0)-(keys.d||keys.arrowright?1:0);if(countdown>0){countdown-=dt;$('raceMessage').textContent=Math.ceil(countdown)>0?Math.ceil(countdown):'СТАРТ';if(countdown<=0)$('raceMessage').textContent='';}else if(!finished){elapsed+=dt;let acc=(6+Math.sqrt(power())*.44)*(mode==='rally'?.78:1);const max=topSpeed()/3.6,gearMax=max*([0,.25,.42,.59,.75,.9,1][dragGear]);if(accelerating)speed+=acc*dt*(mode==='drag'?(Math.abs(speed)<gearMax?1:.01):1);if(braking)speed-=dt*(speed>1?26:5);speed*=Math.exp(-dt*(accelerating?.07:.36));if(keys[' '])speed*=Math.exp(-dt*2.1);speed=T.MathUtils.clamp(speed,-10,max);if(mode==='drag'&&speed>gearMax)speed=Math.max(gearMax,speed-18*dt);heading+=steer*dt*Math.min(Math.abs(speed)/5,1)*1.5/(1+Math.abs(speed)*.025)*(speed>=0?1:-1)*(1+mod().tires*.1);carGroup.position.x-=Math.sin(heading)*speed*dt;carGroup.position.z-=Math.cos(heading)*speed*dt;carGroup.rotation.y=heading;carGroup.rotation.z=T.MathUtils.lerp(carGroup.rotation.z,-steer*Math.min(Math.abs(speed)*.002,.07),.1);if(mode==='rally')carGroup.position.y=Math.sin(elapsed*17)*Math.min(Math.abs(speed)*.002,.06);distance+=Math.abs(speed)*dt;hitCooldown=Math.max(0,hitCooldown-dt);for(const o of obstacles){if(Math.abs(carGroup.position.x-o.x)<o.w/2+.85&&Math.abs(carGroup.position.z-o.z)<o.d/2+1.5){if(hitCooldown===0&&Math.abs(speed)>3){let damage=Math.min(32,Math.abs(speed)*1.05);health=Math.max(0,health-damage);bodyParts.forEach((p,i)=>{p.scale.z=Math.max(.65,1-(100-health)*.003);p.rotation.z=(i?1:-1)*(100-health)*.0007});crashes++;hitCooldown=1;carGroup.position.x+=Math.sin(heading)*speed*dt*3;carGroup.position.z+=Math.cos(heading)*speed*dt*3;speed*=-.3;if(mode==='crash')reward(500);}else speed*=-.15;break;}}let bound=mode==='drag'?490:225;if(Math.abs(carGroup.position.x)>bound||Math.abs(carGroup.position.z)>bound){carGroup.position.x=T.MathUtils.clamp(carGroup.position.x,-bound,bound);carGroup.position.z=T.MathUtils.clamp(carGroup.position.z,-bound,bound);speed*=-.3;}
const multiplier=Math.min(100000,Math.pow(1.35,state.wins));if(mode==='free'){let units=Math.floor(distance/1000);if(units>paidDistance){reward((units-paidDistance)*2000);paidDistance=units;toast('+2 000 $ за километр')}$('objective').textContent=(distance/1000).toFixed(2)+' км · Исследуй дороги и промзону';}if(mode==='race'||mode==='rally'){const c=checkpoints[cp];if(c&&Math.hypot(carGroup.position.x-c.x,carGroup.position.z-c.z)<8){gateObjects[cp].visible=false;cp++;}gateObjects.forEach((g,i)=>{g.visible=i>=cp;g.scale.setScalar(i===cp?1.15:1)});$('objective').textContent=`Ворота ${cp} / ${checkpoints.length} · Лимит ${mode==='rally'?110:100} с`;if(cp===checkpoints.length)finish(true,Math.round((mode==='rally'?20000:15000)*multiplier),'ФИНИШ');else if(elapsed>(mode==='rally'?110:100))finish(false,1500,'ВРЕМЯ ВЫШЛО');if(rival){const target=checkpoints[rivalCp%checkpoints.length],dx=target.x-rival.position.x,dz=target.z-rival.position.z,len=Math.hypot(dx,dz);rival.rotation.y=Math.atan2(-dx,-dz);if(len>1){rival.position.x+=dx/len*9*dt;rival.position.z+=dz/len*9*dt;}if(len<3)rivalCp++;if(rivalCp>=checkpoints.length&&!finished)finish(false,2500,'СОПЕРНИК ФИНИШИРОВАЛ');}}if(mode==='drag'){$('objective').textContent=`${Math.min(402,Math.max(0,Math.round(-carGroup.position.z)))} / 402 м · Shift / + — выше · Ctrl / − — ниже`;rival.position.z=-Math.min(430,elapsed*elapsed*2.3);if(-carGroup.position.z>=402)finish(elapsed<13.22,Math.round((elapsed<13.22?10000:3000)*multiplier),elapsed<13.22?'ПОБЕДА':'ФИНИШ');else if(elapsed>45)finish(false,500,'ВРЕМЯ ВЫШЛО');}if(mode==='crash'){$('objective').textContent=`Удары: ${crashes} · Осталось ${Math.max(0,Math.ceil(45-elapsed))} с`;if(elapsed>=45)finish(true,crashes*500,'АРЕНА ЗАВЕРШЕНА');}if(health<=0)finish(false,mode==='crash'?crashes*250:0,'МАШИНА РАЗБИТА');}
wheels.forEach(w=>w.rotation.x-=speed*dt/.4);desired.set(carGroup.position.x+Math.sin(heading)*9,6.2,carGroup.position.z+Math.cos(heading)*10);camera.position.lerp(desired,1-Math.exp(-dt*5));look.copy(carGroup.position);look.y=1;look.x-=Math.sin(heading)*5;look.z-=Math.cos(heading)*5;camera.lookAt(look);key.position.set(carGroup.position.x+6,17,carGroup.position.z+7);key.target.position.copy(carGroup.position);$('shiftGear').textContent=dragGear;const rpmValue=Math.round(1000+Math.min(1.1,Math.abs(speed)/(topSpeed()/3.6*[0,.25,.42,.59,.75,.9,1][dragGear]))*6000);$('rpm').textContent=rpmValue+' RPM';$('shiftUp').classList.toggle('shiftNow',rpmValue>6100);$('speed').textContent=Math.round(Math.abs(speed)*3.6);$('gear').textContent=mode==='drag'?dragGear:speed<-1?'R':speed<1?'N':Math.min(6,1+Math.floor(speed/12));$('health').textContent=Math.round(health)+'%';$('timer').textContent=elapsed.toFixed(1);}
if(gain){gain.gain.setTargetAtTime(sound?(mode==='garage'?.009:.025):0,audioCtx.currentTime,.1);osc.frequency.setTargetAtTime(mode==='garage'?45:45+Math.abs(speed)*3+((keys.w||keys.arrowup)?22:0),audioCtx.currentTime,.1);}renderer.render(scene,camera);}requestAnimationFrame(tick);
